package com.alpharip.staffmod.IncidentPostMortemBoard;
import net.minecraft.client.gui.GuiButton;import net.minecraft.client.gui.GuiScreen;import net.minecraft.client.gui.GuiTextField;import java.io.IOException;import java.util.List;
/** Initial in-game overview. The caller must provide a real StaffMods authorization adapter. */
public final class IncidentPostMortemGui extends GuiScreen {
 private static final int ADD=1,BACK=2,STATUS=1000,REMOVE=2000;private final GuiScreen parent;private final IncidentPostMortemController controller;private GuiTextField title,description,reporter;private int left,top,right,bottom,scroll;private String message="LOCAL PROTOTYPE";
 public IncidentPostMortemGui(GuiScreen p,IncidentPostMortemController c){if(c==null)throw new IllegalArgumentException("Controller required");parent=p;controller=c;}
 @Override public void initGui(){if(!controller.getAccess().canView()){mc.displayGuiScreen(parent);return;}controller.load();buttonList.clear();int w=Math.min(560,width-20),h=Math.min(390,height-20);left=(width-w)/2;right=left+w;top=(height-h)/2;bottom=top+h;title=new GuiTextField(10,fontRendererObj,left+14,top+54,w-28,18);description=new GuiTextField(11,fontRendererObj,left+14,top+92,w-28,18);reporter=new GuiTextField(12,fontRendererObj,left+14,top+130,w-140,18);title.setMaxStringLength(100);description.setMaxStringLength(240);reporter.setMaxStringLength(32);if(controller.getAccess().canManage())buttonList.add(new GuiButton(ADD,right-116,top+128,102,22,"ADD"));buttonList.add(new GuiButton(BACK,left+14,bottom-28,70,20,"BACK"));rows();}
 private void rows(){for(int i=buttonList.size()-1;i>=0;i--)if(buttonList.get(i).id>=STATUS)buttonList.remove(i);List<IncidentRecord> all=controller.getBoard().getAll();int visible=Math.max(1,(bottom-top-205)/31);scroll=Math.max(0,Math.min(scroll,all.size()-visible));if(controller.getAccess().canManage())for(int i=scroll;i<Math.min(all.size(),scroll+visible);i++){int row=i-scroll,y=top+177+row*31;buttonList.add(new GuiButton(STATUS+row,right-128,y,58,18,"STATUS"));buttonList.add(new GuiButton(REMOVE+row,right-66,y,54,18,"REMOVE"));}}
 @Override public void drawScreen(int mx,int my,float partial){drawDefaultBackground();drawRect(left,top,right,bottom,0xF00D1017);drawRect(left,top,right,top+2,0xFFFFD866);drawCenteredString(fontRendererObj,"INCIDENT POSTMORTEM BOARD",width/2,top+13,0xFFF3F4F6);drawCenteredString(fontRendererObj,"STAFF OPERATIONS · LOCAL PROTOTYPE",width/2,top+29,0xFFFFD866);drawString(fontRendererObj,"TITLE",left+14,top+43,0xFFB8BDC8);title.drawTextBox();drawString(fontRendererObj,"DESCRIPTION",left+14,top+81,0xFFB8BDC8);description.drawTextBox();drawString(fontRendererObj,"REPORTER",left+14,top+119,0xFFB8BDC8);reporter.drawTextBox();IncidentPostMortemSummary s=controller.getService().summarize();drawString(fontRendererObj,"TOTAL "+s.getTotal()+" OPEN "+s.getOpen()+" INVESTIGATING "+s.getInvestigating()+" ACTIONS "+s.getActionRequired()+" CRITICAL "+s.getCritical(),left+14,top+158,0xFFB8BDC8);List<IncidentRecord> all=controller.getBoard().getAll();int visible=Math.max(1,(bottom-top-205)/31);if(all.isEmpty())drawCenteredString(fontRendererObj,"No incidents recorded",width/2,top+205,0xFFB8BDC8);for(int i=scroll;i<Math.min(all.size(),scroll+visible);i++){IncidentRecord r=all.get(i);int y=top+177+(i-scroll)*31;drawRect(left+12,y,right-12,y+27,0xAA191D25);drawString(fontRendererObj,fontRendererObj.trimStringToWidth(r.getTitle(),right-left-180),left+20,y+4,0xFFF3F4F6);drawString(fontRendererObj,r.getSeverity().name()+" · "+r.getStatus().name(),left+20,y+16,0xFFFFD866);}drawString(fontRendererObj,message,left+100,bottom-24,0xFFB8BDC8);super.drawScreen(mx,my,partial);}
 @Override protected void actionPerformed(GuiButton b)throws IOException{if(b.id==BACK){mc.displayGuiScreen(parent);return;}if(!controller.getAccess().canManage())return;if(b.id==ADD){try{controller.getService().create(title.getText(),description.getText(),IncidentCategory.OTHER,IncidentSeverity.MEDIUM,reporter.getText(),System.currentTimeMillis());controller.save();title.setText("");description.setText("");reporter.setText("");message="Incident created";rows();}catch(RuntimeException e){message=e.getMessage();}return;}if(b.id>=STATUS&&b.id<REMOVE){int i=scroll+b.id-STATUS;List<IncidentRecord> all=controller.getBoard().getAll();if(i<all.size()){IncidentRecord r=all.get(i);IncidentStatus[] states=IncidentStatus.values();controller.getService().setStatus(r.getId(),states[(r.getStatus().ordinal()+1)%states.length],System.currentTimeMillis());controller.save();}rows();return;}if(b.id>=REMOVE){int i=scroll+b.id-REMOVE;List<IncidentRecord> all=controller.getBoard().getAll();if(i<all.size())controller.getService().remove(all.get(i).getId());controller.save();rows();}}
 @Override protected void mouseClicked(int x,int y,int button)throws IOException{title.mouseClicked(x,y,button);description.mouseClicked(x,y,button);reporter.mouseClicked(x,y,button);super.mouseClicked(x,y,button);}
 @Override protected void keyTyped(char c,int key)throws IOException{if(key==1){mc.displayGuiScreen(parent);return;}title.textboxKeyTyped(c,key);description.textboxKeyTyped(c,key);reporter.textboxKeyTyped(c,key);super.keyTyped(c,key);}
 @Override public boolean doesGuiPauseGame(){return false;}
}